// In-memory stand-in for a real user preferences store.
// `globalThis` keeps the value stable across dev-mode module reloads.

type Preferences = { notificationsEnabled: boolean }

const store = globalThis as typeof globalThis & {
  __userPreferences?: Preferences
}

store.__userPreferences ??= { notificationsEnabled: false }

export async function getNotificationPreference(): Promise<boolean> {
  return store.__userPreferences!.notificationsEnabled
}

export async function setNotificationPreference(enabled: boolean): Promise<void> {
  store.__userPreferences!.notificationsEnabled = enabled
}

